// MAISON ÉLAN — build-time database provisioning for deployed environments.
// Runs inside `vercel-build` (and `build`) BEFORE `next build`, after the
// Prisma Client has been generated by scripts/prisma-generate.cjs:
//
//   1. `prisma db push` — syncs the PostgreSQL schema to the database (Neon),
//      so a fresh database gets all 25 tables without any manual CLI step.
//   2. `prisma db seed` — fills demo content, but ONLY when the database is
//      still empty (prisma/seed.ts has a built-in guard — production data is
//      never touched on redeploys).
//
// Context rules (mirrors scripts/prisma-generate.cjs):
//   - VERCEL=1 or DATABASE_URL starts with postgres… → provision (push + seed)
//   - otherwise (local SQLite) → no-op; locals manage the DB manually via
//     `bun run db:push` / `bun run db:seed`.
//
// Failure policy:
//   - Schema push failure  → exit 1. A deploy without a working schema is
//     useless; failing the build keeps the previous (working) deployment live.
//   - Seed failure         → warn + exit 0. The site works without demo data;
//     the warning surfaces in build logs for follow-up.

/* eslint-disable @typescript-eslint/no-require-imports -- build-time helper: must stay CommonJS, runs under node/bun before any bundling */

const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const root = process.cwd();

function databaseUrl() {
  if (process.env.DATABASE_URL) return process.env.DATABASE_URL;
  try {
    const envFile = fs.readFileSync(path.join(root, ".env"), "utf8");
    const m = envFile.match(/^DATABASE_URL\s*=\s*"?([^"\r\n#]+)"?/m);
    return m ? m[1].trim() : "";
  } catch {
    return "";
  }
}

const url = databaseUrl();

if (!url) {
  console.warn("[prisma-deploy-db] No DATABASE_URL found (env or .env) — skipping schema push and seed.");
  process.exit(0);
}

const usePostgres = process.env.VERCEL === "1" || url.startsWith("postgres");

if (!usePostgres) {
  console.log("[prisma-deploy-db] SQLite context (local/VPS) — nothing to do. Manage the DB with `bun run db:push` / `bun run db:seed`.");
  process.exit(0);
}

console.log(`[prisma-deploy-db] Postgres context — target ${url.split("@").pop() || "(set)"}`);

// Neon best practice: schema operations prefer the DIRECT (unpooled) string.
// If DIRECT_DATABASE_URL was not configured we fall back to the pooled URL —
// Neon's pooler accepts DDL, so provisioning still works.
const childEnv = { ...process.env };
if (!childEnv.DIRECT_DATABASE_URL) {
  childEnv.DIRECT_DATABASE_URL = url;
  console.log("[prisma-deploy-db] DIRECT_DATABASE_URL not set — falling back to DATABASE_URL (pooled) for schema operations.");
}

const runners = [
  "node_modules/.bin/prisma", // fastest — local CLI binary
  "npx prisma",               // npm-based environments
  "bunx prisma",              // bun-only environments
];

function runFirst(args, label) {
  for (const bin of runners) {
    try {
      execSync(`${bin} ${args}`, { stdio: "inherit", cwd: root, env: childEnv, timeout: 300000 });
      return true;
    } catch {
      // try the next runner
    }
  }
  if (label) console.warn(`[prisma-deploy-db] ${label} — all runners failed.`);
  return false;
}

// ── Step 1/2: schema push ────────────────────────────────────────────────────
console.log("[prisma-deploy-db] Step 1/2 — syncing schema (prisma db push)…");
if (!runFirst("db push --schema prisma/schema.postgres.prisma --skip-generate")) {
  console.error("[prisma-deploy-db] Schema push FAILED — check DATABASE_URL / DIRECT_DATABASE_URL and database reachability.");
  console.error("[prisma-deploy-db] Failing the build so the previous (working) deployment stays live.");
  process.exit(1);
}

// ── Step 2/2: seed (empty-database guard lives in prisma/seed.ts) ───────────
console.log("[prisma-deploy-db] Step 2/2 — seeding demo content (only if the database is empty)…");
const seedCommands = [
  "node_modules/.bin/prisma db seed --schema prisma/schema.postgres.prisma",
  "npx prisma db seed --schema prisma/schema.postgres.prisma",
  "bunx prisma db seed --schema prisma/schema.postgres.prisma",
  "bun prisma/seed.ts",          // direct fallback (no prisma CLI overhead)
  "npx tsx prisma/seed.ts",      // last resort on machines without bun
];

let seeded = false;
for (const cmd of seedCommands) {
  try {
    execSync(cmd, { stdio: "inherit", cwd: root, env: childEnv, timeout: 300000 });
    seeded = true;
    break;
  } catch {
    // try the next seed runner
  }
}

if (!seeded) {
  console.warn("[prisma-deploy-db] Seed FAILED (build continues) — the store will have no demo data.");
  console.warn("[prisma-deploy-db] Re-seed manually later: bun run db:generate:pg && bun run db:seed:pg");
} else {
  console.log("[prisma-deploy-db] done.");
}
process.exit(0);
